import { readdir, writeFile } from "node:fs/promises";
import path from "node:path";

const commandsDirectory = path.join(process.cwd(), "src", "commands");
const excluded = new Set(["types.ts", "generated.ts"]);
const files = (await readdir(commandsDirectory))
  .filter((file) => file.endsWith(".ts") && !excluded.has(file))
  .sort();

const imports = files.map(
  (file, index) =>
    `import command${index} from "./${file.replace(/\.ts$/, "")}";`,
);
const output = [
  "// Generated by scripts/generate-command-registry.mjs. Do not edit.",
  ...imports,
  "",
  'import type { AutomationCommand } from "./types";',
  "",
  "export const generatedCommands: AutomationCommand[] = [",
  ...files.map((_, index) => `  command${index},`),
  "];",
  "",
].join("\n");

await writeFile(path.join(commandsDirectory, "generated.ts"), output, "utf8");
